package com.openggf.game.soniccd.level;
import com.openggf.game.soniccd.player.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.openggf.game.soniccd.level.TestCdR31aPlayerFrameEntry.*;
/** Tests FIRST; actual R31 source, explicitly CONSTRUCTED dirty complete player pairs.
 * Successes come only from shared Body.step; no fabricated Result/physics/terrain or Main/Hurt completion. */
class TestCdR31aPlayerBodyInit {
 @Test void nativeInitUsesActualLocalMappingAndExactOriginalWriteOrder()throws Exception{var source=CdStagePlayerSource.fromR31aAssets(actual());var body=CdPlayerBody.fromStageSource(source);var state=state(0,0x42,0);var env=environment(0x100,1,0,0,0x34);var result=body.step(state,env);assertInit(state,env,result,false);assertEquals(List.of(new CdPlayerBody.CallReturned(CdPlayerBody.NativeCall.CHARGE_BEFORE_DISPATCH),new CdPlayerBody.ActorWrite(CdPlayerBody.ActorField.ROUTINE,2),new CdPlayerBody.ActorWrite(CdPlayerBody.ActorField.Y_RADIUS,19),new CdPlayerBody.ActorWrite(CdPlayerBody.ActorField.X_RADIUS,9),new CdPlayerBody.ActorWrite(CdPlayerBody.ActorField.MAPPING_ADDRESS,0x22DF20),new CdPlayerBody.ActorWrite(CdPlayerBody.ActorField.TILE,0x780),new CdPlayerBody.ActorWrite(CdPlayerBody.ActorField.PRIORITY,2),new CdPlayerBody.ActorWrite(CdPlayerBody.ActorField.WIDTH,0x18),new CdPlayerBody.ActorWrite(CdPlayerBody.ActorField.SPRITE_FLAGS,4),new CdPlayerBody.GlobalWrite(CdPlayerBody.GlobalField.TOP_SPEED,0x600),new CdPlayerBody.GlobalWrite(CdPlayerBody.GlobalField.ACCELERATION,12),new CdPlayerBody.GlobalWrite(CdPlayerBody.GlobalField.DECELERATION,0x80),new CdPlayerBody.CallReturned(CdPlayerBody.NativeCall.INIT)),result.effects());assertThrows(CdR11aPlayerAssets.UnownedPpzRamp.class,source.player()::rampChunks);}
 @Test void nativeNonzeroShrunkInitWritesNormalThenMiniRadiiWithoutOtherMiniGameplayAdmission()throws Exception{var body=CdPlayerBody.fromStageSource(CdStagePlayerSource.fromR31aAssets(actual()));for(int mini:new int[]{1,0x80,255}){var s=state(0,0x42,0);var e=environment(0x100,1,mini,0,0);var result=body.step(s,e);assertInit(s,e,result,true);var writes=result.effects().stream().filter(x->x instanceof CdPlayerBody.ActorWrite w&&(w.field()==CdPlayerBody.ActorField.Y_RADIUS||w.field()==CdPlayerBody.ActorField.X_RADIUS)).toList();assertEquals(List.of(new CdPlayerBody.ActorWrite(CdPlayerBody.ActorField.Y_RADIUS,19),new CdPlayerBody.ActorWrite(CdPlayerBody.ActorField.X_RADIUS,9),new CdPlayerBody.ActorWrite(CdPlayerBody.ActorField.Y_RADIUS,10),new CdPlayerBody.ActorWrite(CdPlayerBody.ActorField.X_RADIUS,5)),writes);}}
 @Test void allMainHurtDeadRestartAndControlledContinuationsStopBeforeAnyChargeOrHelperPrefix()throws Exception{var body=CdPlayerBody.fromStageSource(CdStagePlayerSource.fromR31aAssets(actual()));for(int routine:new int[]{2,4,6,8,10})for(int control:new int[]{0,1,0x40,0x80}){var s=state(routine,0x42,0x20,control);var e=environment(0x100,1,0,0,0);var error=assertThrows(CdPlayerBody.UnsupportedBody.class,()->body.step(s,e));assertEquals(CdPlayerBody.UnsupportedBoundary.R3_CONTINUATION_OWNER,error.boundary());assertEquals(0x20,s.motion().charge());assertEquals(routine,s.motion().routine());assertEquals(0xFFF1,s.history().index());}}
 @Test void exactRawWordAndPeriodRejectBeforeNativeChargeOrRadiiWrites()throws Exception{var body=CdPlayerBody.fromStageSource(CdStagePlayerSource.fromR31aAssets(actual()));var s=state(0,0x42,0x20);for(var raw:List.of(new int[]{0,1},new int[]{1,1},new int[]{0x101,1},new int[]{0x100,0},new int[]{0x100,2},new int[]{0x100,0x81})){var e=environment(raw[0],raw[1],0,0,0);assertEquals(CdPlayerBody.UnsupportedBoundary.SOURCE_FAMILY,assertThrows(CdPlayerBody.UnsupportedBody.class,()->body.step(s,e)).boundary());assertEquals(0x20,s.motion().charge());}}
 @Test void absentSlotAndWrongPrimaryIdKeepTheirOriginalIndependentGuards()throws Exception{var body=CdPlayerBody.fromStageSource(CdStagePlayerSource.fromR31aAssets(actual()));var s=state(4,0x42,0x20);var absent=header(s,0);var e=environment(0,0x82,1,0,0x100);var result=body.step(absent,e);assertEquals(CdPlayerBody.Boundary.SLOT_ABSENT,result.boundary());assertSame(absent,result.state());assertSame(e,result.environment());assertTrue(result.effects().isEmpty());assertEquals(CdPlayerBody.UnsupportedBoundary.SLOT_ID,assertThrows(CdPlayerBody.UnsupportedBody.class,()->body.step(header(s,2),environment(0x100,1,0,0,0))).boundary());}
 @Test void nativeDebugAndTimeAttackOrderingRemainBeforeInitPredispatch()throws Exception{var body=CdPlayerBody.fromStageSource(CdStagePlayerSource.fromR31aAssets(actual()));var s=state(0,0x42,0);assertEquals(CdPlayerBody.UnsupportedBoundary.DEBUG_UPDATE,assertThrows(CdPlayerBody.UnsupportedBody.class,()->body.step(s,environment(0x100,1,0,0,0x100))).boundary());var attack=environment(0x100,1,0,1,0x100);assertInit(s,attack,body.step(s,attack),false);}
 @Test void actualPredispatchByteCapsAndWrapAreSharedOnceBeforeTheInitReturn()throws Exception{var body=CdPlayerBody.fromStageSource(CdStagePlayerSource.fromR31aAssets(actual()));int[][] vectors={{0x42,0x20,0x1E},{0x46,0x30,0x2D},{0x42,255,0},{0x46,0,0}};for(var v:vectors){var result=body.step(state(0,v[0],v[1]),environment(0x100,1,0,0,0));assertEquals(v[2],result.state().motion().charge());assertEquals(1,result.effects().stream().filter(x->x instanceof CdPlayerBody.CallReturned r&&r.call()==CdPlayerBody.NativeCall.CHARGE_BEFORE_DISPATCH).count());assertEquals(CdPlayerBody.Boundary.INIT_RETURN,result.boundary());assertTrue(result.display().isEmpty());assertTrue(result.modeBoundary().isEmpty());}}
 @Test void oldPpzInitAndMiniatureRejectionKeepTheirExactContract()throws Exception{var a=TestCdR31aPlayerCoreAssets.actual().present();var body=new CdPlayerBody(a);var s=state(0,0x42,0);var e=environment(0,1,0,0,0);var result=body.step(s,e);assertEquals(CdPlayerBody.Boundary.INIT_RETURN,result.boundary());assertEquals(a.profile().range(CdR11aAsset.MAP_SPR_SONIC).nativeAddress(),result.state().header().mappingAddress());assertEquals(9,result.state().motion().xRadius());assertEquals(19,result.state().motion().yRadius());assertEquals(CdPlayerBody.UnsupportedBoundary.MINIATURE_INIT,assertThrows(CdPlayerBody.UnsupportedBody.class,()->body.step(s,environment(0,1,1,0,0))).boundary());assertEquals(CdPlayerBody.UnsupportedBoundary.SOURCE_FAMILY,assertThrows(CdPlayerBody.UnsupportedBody.class,()->body.step(s,environment(0x100,1,0,0,0))).boundary());}
 @Test void initNeverSelectsMainDisplayAnimateHistoryTerrainOrTouchDespiteDirtyIngress()throws Exception{var body=CdPlayerBody.fromStageSource(CdStagePlayerSource.fromR31aAssets(actual()));var s=state(0,0x42,0);var e=environment(0x100,1,0,0,0);var result=body.step(s,e);assertTrue(result.display().isEmpty());assertTrue(result.modeBoundary().isEmpty());assertEquals(List.of(CdPlayerBody.NativeCall.CHARGE_BEFORE_DISPATCH,CdPlayerBody.NativeCall.INIT),result.effects().stream().filter(CdPlayerBody.CallReturned.class::isInstance).map(CdPlayerBody.CallReturned.class::cast).map(CdPlayerBody.CallReturned::call).toList());assertSame(s.history(),result.state().history());assertEquals(s.animation(),result.state().animation());assertSame(e.dynamicSlots(),result.environment().dynamicSlots());}
 @Test void unchangedMovementStillRejectsRealR31ModeBeforeAnyUnownedRampOrTerrainCall()throws Exception{var source=CdStagePlayerSource.fromR31aAssets(actual());var movement=CdPlayerMovement.fromStageSource(source);var s=state(2,0x42,0);var e=environment(0x100,1,0,0,0);var error=assertThrows(CdPlayerMovement.UnsupportedMotion.class,()->movement.step(s.motion(),new CdPlayerMovement.Input(0,0),e.movement()));assertEquals(CdPlayerMovement.UnsupportedBoundary.SOURCE_FAMILY,error.boundary());assertEquals(2,s.motion().routine());}
 static void assertInit(CdPlayerBody.State before,CdPlayerBody.Environment environment,CdPlayerBody.Result result,boolean mini){assertEquals(CdPlayerBody.Boundary.INIT_RETURN,result.boundary());var b=before.motion();var a=result.state().motion();assertEquals(new CdPlayerMotionState(b.centreX16_16(),b.centreY16_16(),b.xVelocity(),b.yVelocity(),b.groundVelocity(),2,b.angle(),b.flags(),4,mini?5:9,mini?10:19,b.animation(),b.previousAnimation(),b.playerJump(),b.charge(),b.moveLock(),b.stick(),b.playerControl(),b.previousPrimaryAngle(),b.previousSecondaryAngle()),a);assertEquals(new CdPlayerBody.Header(1,0x22DF20,0x780,2,0x18),result.state().header());assertEquals(before.animation(),result.state().animation());assertEquals(before.timers(),result.state().timers());assertSame(before.history(),result.state().history());assertSame(before.objectLinks(),result.state().objectLinks());assertEquals(before.rotationDistance(),result.state().rotationDistance());assertEquals(before.rotationAngle(),result.state().rotationAngle());assertEquals(new CdPlayerMovement.Physics(0x600,12,0x80),result.environment().movement().physics());assertSame(environment.movement().bounds(),result.environment().movement().bounds());assertSame(environment.movement().gates(),result.environment().movement().gates());assertEquals(environment.movement().globals(),result.environment().movement().globals());assertSame(environment.controls(),result.environment().controls());assertEquals(environment.globals(),result.environment().globals());assertSame(environment.dynamicSlots(),result.environment().dynamicSlots());assertTrue(result.display().isEmpty());assertTrue(result.modeBoundary().isEmpty());}
 private static CdPlayerBody.State header(CdPlayerBody.State s,int id){return new CdPlayerBody.State(s.motion(),s.animation(),new CdPlayerBody.Header(id,s.header().mappingAddress(),s.header().tile(),s.header().priority(),s.header().width()),s.timers(),s.history(),s.rotationDistance(),s.objectLinks(),s.rotationAngle());}
}
